PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('analyst','viewer')));
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, ts TEXT NOT NULL, kind TEXT NOT NULL, src TEXT NOT NULL, body TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS event_time ON events(ts);
CREATE TABLE IF NOT EXISTS alerts(id TEXT PRIMARY KEY, rule TEXT NOT NULL, src TEXT NOT NULL, ts TEXT NOT NULL, score INTEGER NOT NULL, reason TEXT NOT NULL, evidence TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open');
CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY, alert_id TEXT NOT NULL REFERENCES alerts(id), actor TEXT NOT NULL, ts TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, actor TEXT NOT NULL, ts TEXT NOT NULL, action TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attempts(ip TEXT PRIMARY KEY, started REAL NOT NULL, count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS collectors(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, owner_id INTEGER NOT NULL REFERENCES users(id), token_hash TEXT UNIQUE NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, created TEXT NOT NULL, last_seen TEXT, received INTEGER NOT NULL DEFAULT 0, last_error TEXT, window_start REAL NOT NULL DEFAULT 0, requests INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS event_sources(event_id TEXT NOT NULL REFERENCES events(id), collector_id INTEGER NOT NULL REFERENCES collectors(id), PRIMARY KEY(event_id,collector_id));
CREATE TABLE IF NOT EXISTS ai_summaries(id INTEGER PRIMARY KEY, alert_id TEXT NOT NULL REFERENCES alerts(id), actor TEXT NOT NULL, ts TEXT NOT NULL, model TEXT NOT NULL, content TEXT NOT NULL, facts TEXT NOT NULL);
